<script setup>
import {ref,reactive,watch,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorText} from '../../services/api'
import {reasons,states,date,validateFiles} from '../../services/property'
import AppShell from './AppShell.vue'
import Pager from './Pager.vue'
import ReportDetails from './ReportDetails.vue'
const route=useRoute(),router=useRouter(),creating=computed(()=>!!route.params.id),busy=ref(false),error=ref(''),notice=ref(''),property=ref(null),data=ref({items:[],page:0,totalPages:0,totalElements:0}),selected=ref(null),created=ref(null),files=ref([]),form=reactive({reasonCode:'OTHER',description:'',contactEmail:''})
async function load(page=0){busy.value=true;error.value='';try{if(creating.value)property.value=await api('/properties/'+route.params.id);else data.value=await api('/users/me/reports?page='+page+'&size=10')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function choose(event){try{const chosen=Array.from(event.target.files);validateFiles(chosen,true);if(chosen.length+files.value.length+(created.value?.attachments.length||0)>10)throw new Error('Tối đa 10 tệp bằng chứng.');files.value.push(...chosen);error.value=''}catch(e){error.value=e.message}event.target.value=''}
async function send(){if(busy.value)return;busy.value=true;error.value='';try{if(!created.value)created.value=await api('/properties/'+route.params.id+'/reports',{method:'POST',body:{...form,contactEmail:form.contactEmail||null}});while(files.value.length){const data=new FormData();data.append('file',files.value[0]);created.value=await api('/reports/'+created.value.id+'/attachments',{method:'POST',body:data});files.value.shift()}await router.push('/account/reports')}catch(e){error.value=errorText(e)+(created.value?' Báo cáo đã tạo; bạn có thể gửi lại các tệp còn thiếu.':'')}finally{busy.value=false}}
async function detail(id){busy.value=true;try{selected.value=await api('/reports/'+id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function updated(report){selected.value=report;const i=data.value.items.findIndex(r=>r.id===report.id);if(i>=0)data.value.items[i]=report}
watch(()=>route.path,()=>{selected.value=null;created.value=null;load()},{immediate:true})
</script>
<template><AppShell><h1>{{creating?'Báo cáo tin đăng':'Báo cáo của tôi'}}</h1><p v-if="error" role="alert" class="sp-error">{{error}} <button @click="load(data.page)">Tải lại</button></p><p v-if="busy" role="status">Đang xử lý…</p><p v-if="notice" class="sp-success">{{notice}}</p>
<form v-if="creating&&property" class="sp-panel sp-form" @submit.prevent="send"><h2 class="sp-wide">{{property.title}}</h2><label class="sp-wide">Lý do<select v-model="form.reasonCode" :disabled="!!created"><option v-for="(label,key) in reasons" :key="key" :value="key">{{label}}</option></select></label><label class="sp-wide">Mô tả<textarea v-model="form.description" required maxlength="10000" :disabled="!!created"></textarea></label><label class="sp-wide">Email liên hệ (không bắt buộc)<input v-model="form.contactEmail" type="email" maxlength="254" :disabled="!!created"></label><label class="sp-wide">Bằng chứng JPEG/PNG/PDF, tối đa 10 MB/tệp<input type="file" accept="image/jpeg,image/png,application/pdf" multiple :disabled="busy" @change="choose"></label><ul class="sp-wide"><li v-for="(file,index) in files" :key="index">{{file.name}} <button type="button" :disabled="busy" @click="files.splice(index,1)">Bỏ chọn</button></li></ul><div class="sp-wide"><button class="sp-primary" :disabled="busy">{{created?'Gửi các tệp còn lại':'Gửi báo cáo'}}</button></div></form>
<template v-if="!creating"><div v-if="!busy&&!error&&!data.items.length" class="sp-empty">Bạn chưa gửi báo cáo nào.</div><section v-for="report in data.items" :key="report.id" class="sp-panel sp-row sp-spread"><div><span class="sp-tag">{{states[report.status]}}</span><h3>{{reasons[report.reasonCode]||report.reasonCode}}</h3><p class="sp-muted">{{date(report.createdAt)}}</p></div><button :disabled="busy" @click="detail(report.id)">Xem nội dung và bằng chứng</button></section><Pager v-bind="data" :busy="busy" @change="load"/><ReportDetails v-if="selected" :report="selected" @updated="updated"/></template>
</AppShell></template>